# 高风险动作的风险分级与执行前 Gate（伪代码）
RISK_TIERS = {
    "read_only_query": "LOW",        # 只读，无副作用，直接放行
    "draft_save": "LOW",             # 可完全回滚
    "send_internal_message": "MEDIUM",
    "transfer_money": "HIGH",
    "delete_production_data": "CRITICAL",
}

def dispatch_tool_call(action, params, actor):
    tier = RISK_TIERS.get(action.name, "HIGH")  # 未知动作默认按高风险处理

    # 1. 参数校验：确定性代码先拦一道，不进模型判断
    if not validate_params(action, params):
        return reject("参数越界或格式非法")

    # 2. 权限校验：最小权限、按任务下发的短时凭证
    if not actor.has_scope(action.required_scope):
        return reject("当前身份无此操作权限")

    # 3. 高风险动作需要人工审批，审批者与提议者分离
    if tier in ("HIGH", "CRITICAL"):
        approval = request_approval(
            action=action, params=params, actor=actor,
            blast_radius=estimate_blast_radius(action, params),
        )
        if not approval.granted:
            return reject(f"未获审批：{approval.reason}")

    # 4. 执行并写审计日志（谁、什么参数、谁批准、结果）
    result = execute(action, params)
    audit_log.write(actor, action, params, tier, result)
    return result

# 轻量级 Gate：在调用 LLM 之前用确定性代码先拒绝掉一批请求
def pre_llm_gate(request, user_ctx):
    # 客观事实层校验，不需要语义理解
    if request.amount is not None and request.amount > user_ctx.approval_free_limit:
        return deny("金额超过免审批上限，直接转人工审批流程")

    if not user_ctx.has_scope(request.target_resource_scope):
        return deny("当前用户无该资源访问权限")

    if not resource_exists(request.target_id):
        return deny("目标资源不存在或已被删除")

    # Gate 通过，不代表跳过语义判断，只是省掉了必然被拒绝请求的推理成本
    return allow_and_continue_to_agent(request)

# Gate 与模型判断冲突时：Gate 的拒绝结果具有一票否决权
def dispatch(request, user_ctx):
    gate_result = pre_llm_gate(request, user_ctx)
    if gate_result.denied:
        return gate_result  # 即使模型后续认为该请求"看起来合理"，也不覆盖 Gate 的拒绝

    return run_agent(request)
